    ClearHermesCache("Clear Hermes conversation cache","清除 Hermes 对话缓存","Qīngchú Hermes duìhuà huǎncún"),
    PhoneAi("On-device AI","设备端 AI","Shèbèi duān AI"),
    PhoneBoundary("Runs on this phone. It cannot access Hermes chats, projects or tools. Nothing is sent to Hermes automatically.","在此手机上运行。无法访问 Hermes 聊天、项目或工具。不会自动向 Hermes 发送内容。","Zài cǐ shǒujī shàng yùnxíng. Wúfǎ fǎngwèn Hermes liáotiān, xiàngmù huò gōngjù. Bú huì zìdòng xiàng Hermes fāsòng nèiróng."),
    PhoneEntry("Chat offline, manage models, or read the setup guide. Start a separate local draft; remote requests are never copied or retried.","离线聊天、管理模型或阅读设置指南。新建独立本地草稿，不复制或重试远程请求。","Líxiàn liáotiān, guǎnlǐ móxíng huò yuèdú shèzhì zhǐnán. Xīnjiàn dúlì běndì cǎogǎo, bù fùzhì huò chóngshì yuǎnchéng qǐngqiú."),
    PhoneModels("Phone models","手机模型","Shǒujī móxíng"),
    PhoneHistory("Phone history","手机历史","Shǒujī lìshǐ"),
    PhoneUnsupported("Inference requires a 64-bit app process. The setup guide and Hermes connection remain available.","推理需要 64 位应用进程。仍可使用设置指南和 Hermes 连接。","Tuīlǐ xūyào liùshísì wèi yìngyòng jìnchéng. Réng kě shǐyòng shèzhì zhǐnán hé Hermes liánjiē."),
    PhoneNotLoaded("No model loaded. Open Phone models to import or download a compatible GGUF, then load it.","未加载模型。请打开手机模型，导入或下载兼容的 GGUF 后加载。","Wèi jiāzài móxíng. Qǐng dǎkāi shǒujī móxíng, dǎorù huò xiàzài jiānróng de GGUF hòu jiāzài."),
    PhoneLoaded("Loaded on phone: {model}","手机已加载：{model}","Shǒujī yǐ jiāzài: {model}"),
    PhoneLoad("Load model","加载模型","Jiāzài móxíng"),
    PhoneUnload("Unload model","卸载内存中的模型","Xièzài nèicún zhōng de móxíng"),
    PhoneContext("Context size (tokens)","上下文大小（词元）","Shàngxiàwén dàxiǎo (cíyuán)"),
    PhoneLibraryHelp("Imported files are copied into private app storage (up to 4 GiB each). Supported GGUF metadata does not guarantee a successful native load. Smaller contexts use less memory.","导入文件将复制到应用私有存储（每个最多 4 GiB）。支持 GGUF 元数据不代表原生加载一定成功。较小上下文更省内存。","Dǎorù wénjiàn jiāng fùzhì dào yìngyòng sīyǒu cúnchǔ (měi gè zuìduō sì GiB). Zhīchí GGUF yuán shùjù bù dàibiǎo yuánshēng jiāzài yídìng chénggōng. Jiào xiǎo shàngxiàwén gèng shěng nèicún."),
    PhoneImport("Import GGUF file","导入 GGUF 文件","Dǎorù GGUF wénjiàn"),
    PhoneDownload("Review licence and download","查看许可并下载","Chákàn xǔkě bìng xiàzài"),
    PhoneDownloadInfo("Optional download: 1,049,615,680 bytes, pinned publisher SHA-256. Model weights have a separate licence and are not bundled with the app.","可选下载：1,049,615,680 字节，使用固定发布方 SHA-256。模型权重有独立许可，未随应用捆绑。","Kěxuǎn xiàzài: 1,049,615,680 zìjié, shǐyòng gùdìng fābù fāng SHA-256. Móxíng quánzhòng yǒu dúlì xǔkě, wèi suí yìngyòng kǔnbǎng."),
    PhonePartial("Saved download: {bytes} MiB. Resume is explicit; a server that cannot resume will leave the partial file intact.","已保存下载：{bytes} MiB。需要手动恢复；若服务器不支持，将保留部分文件。","Yǐ bǎocún xiàzài: {bytes} MiB. Xūyào shǒudòng huīfù; ruò fúwùqì bù zhīchí, jiāng bǎoliú bùfen wénjiàn."),
    PhoneDiscard("Discard partial download","丢弃部分下载","Diūqì bùfen xiàzài"),
    PhoneLicence("Model licence review","模型许可审阅","Móxíng xǔkě shěnyuè"),
    PhoneLicenceAccept("I have reviewed the model licence and may use these weights.","我已阅读模型许可，并有权使用这些权重。","Wǒ yǐ yuèdú móxíng xǔkě, bìng yǒuquán shǐyòng zhèxiē quánzhòng."),
    PhoneImportLicence("Review the licence from your model's publisher before importing. A local hash identifies the file; it does not verify the publisher or grant a licence.","导入前请阅读模型发布方的许可。本地哈希用于识别文件，不验证发布方，也不授予许可。","Dǎorù qián qǐng yuèdú móxíng fābù fāng de xǔkě. Běndì hāxī yòngyú shíbié wénjiàn, bù yànzhèng fābù fāng, yě bù shòuyǔ xǔkě."),
    PhonePublisher("Matches the pinned LFM3 publisher hash. Integrity is checked again before loading.","与固定的 LFM3 发布方哈希一致。加载前将再次检查完整性。","Yǔ gùdìng de LFM3 fābù fāng hāxī yízhì. Jiāzài qián jiāng zàicì jiǎnchá wánzhěngxìng."),
    PhoneImported("User-imported model. Review its publisher, licence and compatibility.","用户导入的模型。请检查发布方、许可与兼容性。","Yònghù dǎorù de móxíng. Qǐng jiǎnchá fābù fāng, xǔkě yǔ jiānróngxìng."),
    PhoneMismatch("This chat belongs to another model. Load that model or explicitly start a new chat.","此聊天属于另一模型。请加载对应模型，或明确新建聊天。","Cǐ liáotiān shǔyú lìng yī móxíng. Qǐng jiāzài duìyìng móxíng, huò míngquè xīnjiàn liáotiān."),
    PhoneTurnLimit("This chat has reached 30 turns. Start a new chat; older messages remain in Phone history.","此聊天已达 30 轮。请新建聊天；旧消息仍保留在手机历史中。","Cǐ liáotiān yǐ dá sānshí lún. Qǐng xīnjiàn liáotiān; jiù xiāoxī réng bǎoliú zài shǒujī lìshǐ zhōng."),
    PhoneEmpty("Start a new conversation on this phone. Local answers may be inaccurate; review them before acting.","在此手机上开始新对话。本地回答可能不准确，请核实后再行动。","Zài cǐ shǒujī shàng kāishǐ xīn duìhuà. Běndì huídá kěnéng bù zhǔnquè, qǐng héshí hòu zài xíngdòng."),
    PhoneQuestionLimit("Keep each question within 8 KiB of UTF-8 text.","每个问题请限制在 8 KiB 的 UTF-8 文本内。","Měi gè wèntí qǐng xiànzhì zài bā KiB de UTF-8 wénběn nèi."),
    PhoneDeleteModel("Delete this model file from the phone? It will first be unloaded. Conversations remain, but need this same model to continue.","从手机删除此模型文件？将先卸载内存中的模型。聊天会保留，但继续聊天需要相同模型。","Cóng shǒujī shānchú cǐ móxíng wénjiàn? Jiāng xiān xièzài nèicún zhōng de móxíng. Liáotiān huì bǎoliú, dàn jìxù liáotiān xūyào xiāngtóng móxíng."),
    PhoneDeleteChat("Delete only this phone conversation? Hermes history is unaffected.","仅删除此手机对话？Hermes 历史不受影响。","Jǐn shānchú cǐ shǒujī duìhuà? Hermes lìshǐ bú shòu yǐngxiǎng."),
