    KanbanTaskReasoningOverride("Change task reasoning override","更改任务推理覆盖","Gēnggǎi rènwù tuīlǐ fùgài"),
    KanbanTaskClearModel("Clear model and provider override","清除模型和提供商覆盖","Qīngchú móxíng hé tígōngshāng fùgài"),
