    HostProjectMissingActive("The reported active project is absent from this list.","报告的活动项目不在此列表中。","Bàogào de huódòng xiàngmù bú zài cǐ lièbiǎo zhōng."),
    HostProjectsSnapshot("Observed: {time}","观测时间：{time}","Guāncè shíjiān: {time}"),
